def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    target_remaining = 0.1
    deviation = np.abs(remaining - target_remaining)
    scores = np.maximum(0.0, 1.0 - deviation)
    return np.where(remaining < 0, -np.inf, scores)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    optimal_buffer = 0.05 * bins
    diff_sq = (remaining - optimal_buffer) ** 2
    scores = 1.0 / (1.0 + diff_sq)
    return np.where(remaining < 0, -np.inf, scores)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    optimal_buffer = 0.05 * bins
    diff = remaining - optimal_buffer
    scores = np.exp(-(diff ** 2) / (2.0 * (0.1 * bins + 1e-8) ** 2))
    return np.where(remaining < 0, -np.inf, scores)
